def merge(y, z):
    if not len(y) or not len(z):
        return y or z
    result = []
    i = 0
    j = 0
    while (len(result) < len(y) + len(z)):
        if y[i] < z[j]:
            result.append(y[i])
            i += 1
        else:
            result.append(z[j])
            j += 1
        if i == len(y) or j == len(z):
            result.extend(y[i:] or z[j:])
            break
    return result
