def enforce_type_hinting(func):
    from functools import wraps
    import inspect

    # Get the argument annotations of the original function
    arg_annotations = inspect.getfullargspec(func).annotations

    @wraps(func)
    def wrapper(*args, **kwargs):
        # Checking that the function is called with correct positional arguments
        if len(arg_annotations) != len(args):
            raise TypeError("The number of arguments does not match the function specification.")

        # Check the types of positional arguments
        for (arg, annotation), value in zip(arg_annotations.items(), args):
            if type(value) is not annotation:
                raise TypeError(f"The argument '{arg}' is not of the expected type {annotation}.")

        # Check the types of keyword arguments
        for arg, value in kwargs.items():
            if arg in arg_annotations and not isinstance(value, arg_annotations[arg]):
                raise TypeError(f"The argument '{arg}' is not of the expected type {arg_annotations[arg]}.")

        result = func(*args, **kwargs)

        # Check the type of the result
        result_annotation = inspect.signature(func).return_annotation
        if result_annotation is not inspect._empty and not isinstance(result, result_annotation):
            raise TypeError(f"The return value is not of the expected type {result_annotation}.")

        return result

    return wrapper


