class DocumentationGenerator:
    def __init__(self):
        self.lua_comments = []
        self.xml_comments = []

    def extract_comments(self, file_path):
        if file_path.suffix == '.lua':
            with open(file_path, 'r') as file:
                content = file.read()
                self.lua_comments.extend(self.extract_lua_comments(content))
        elif file_path.suffix == '.xml':
            self.extract_xml_comments(file_path)

    def extract_lua_comments(self, content):
        comments = []
        start = content.find('--[[')
        while start != -1:
            end = content.find(']]', start)
            if end != -1:
                comments.append(content[start + 4:end].strip())
                start = content.find('--[[', end)
            else:
                break
        return comments

    def extract_xml_comments(self, file_path):
        tree = etree.parse(str(file_path))
        for element in tree.iter():
            if element.tag.endswith('comment'):
                self.xml_comments.append(element.text.strip())

    def generate_readme(self, directory):
        readme_content = "# Extension Documentation\n\n"
        readme_content += "## Table of Contents\n"
        readme_content += "- [Lua Documentation](#lua-documentation)\n"
        readme_content += "- [XML Documentation](#xml-documentation)\n\n"
        readme_content += "## Lua Documentation\n"
        for comment in self.lua_comments:
            readme_content += f"- {comment}\n"
        readme_content += "\n## XML Documentation\n"
        for comment in self.xml_comments:
            readme_content += f"- {comment}\n"
        with open(f"{directory}/README.md", 'w') as readme_file:
            readme_file.write(readme_content)

    def generate_documentation_readme(self, directory):
        path = Path(directory)
        for file in path.rglob('*'):
            if file.is_file():
                self.extract_comments(file)
        self.generate_readme(directory)

