count_good_pairs <- function(root, distance) {
  count <- 0

  dfs <- function(node) {
    leaves <- list()

    if (is.null(node$left) && is.null(node$right)) {
      return(list(list(node, 0)))
    }

    if (!is.null(node$left)) {
      left <- dfs(node$left)
      if (left[[1]][[2]] + 1 < distance) {
        leaves <- c(leaves, left)
      }
    }

    if (!is.null(node$right)) {
      right <- dfs(node$right)
      if (right[[1]][[2]] + 1 < distance) {
        leaves <- c(leaves, right)
      }
    }

    for (i in 1:length(leaves)) {
      for (j in (i+1):length(leaves)) {
        leaf1 <- leaves[[i]][[1]]
        dist1 <- leaves[[i]][[2]]
        leaf2 <- leaves[[j]][[1]]
        dist2 <- leaves[[j]][[2]]
        if (dist1 + dist2 + 2 <= distance) {
          count <<- count + 1
        }
      }
    }

    return(lapply(leaves, function(x) list(x[[1]], x[[2]] + 1)))
  }

  dfs(root)
  return(count)
}
