#include <thread>
#include <mutex>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>

const int SERVER_PORT = 8080;
const int BUFFER_SIZE = 1024;

class Client {
public:
    int socket;
    sockaddr_in address;

    Client(int sock, sockaddr_in addr) : socket(sock), address(addr) {}
};

std::vector<Client> clients;
std::mutex clients_mutex;

void accept_connections(int server_socket) {
    while (true) {
        sockaddr_in client_address;
        socklen_t client_address_size = sizeof(client_address);
        int client_socket = accept(server_socket, (sockaddr *)&client_address, &client_address_size);

        if (client_socket == -1) {
            std::cerr << "Error accepting connection" << std::endl;
            continue;
        }

        clients_mutex.lock();
        clients.push_back(Client(client_socket, client_address));
        clients_mutex.unlock();

        std::cout << "New client connected: " << inet_ntoa(client_address.sin_addr) << ":" << ntohs(client_address.sin_port) << std::endl;
    }
}

void receive_messages() {
    char buffer[BUFFER_SIZE];

    while (true) {
        clients_mutex.lock();
        for (Client &client : clients) {
            ssize_t bytes_received = recv(client.socket, buffer, BUFFER_SIZE - 1, MSG_DONTWAIT);

            if (bytes_received <= 0) {
                continue;
            }

            buffer[bytes_received] = '\0';
            std::string message(buffer);

            // Broadcast the message to all other clients
            for (Client &other_client : clients) {
                if (&other_client != &client) {
                    send(other_client.socket, message.c_str(), message.length(), 0);
                }
            }
        }
        clients_mutex.unlock();

        usleep(100000); // Sleep for a short time to reduce CPU usage
    }
}

int main() {
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        std::cerr << "Error creating socket" << std::endl;
        return 1;
    }

    sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(SERVER_PORT);

    if (bind(server_socket, (sockaddr *)&server_address, sizeof(server_address)) == -1) {
        std::cerr << "Error binding socket" << std::endl;
        return 1;
    }

    if (listen(server_socket, SOMAXCONN) == -1) {
        std::cerr << "Error listening on socket" << std::endl;
        return 1;
    }

    std::cout << "Server started on port " << SERVER_PORT << std::endl;

    std::thread accept_thread(accept_connections, server_socket);
    std::thread receive_thread(receive_messages);

    accept_thread.join();
    receive_thread.join();

    return 0;
}

