    let mut word_chars = word.to_lowercase().chars().filter(|c| c.is_alphanumeric());
    while let (Some(front), Some(back)) = (word_chars.next(), word_chars.next_back()) {
        if front != back {
            return false;
        }
    }
    true
}

fn main() {
    let input = "A man, a plan, a canal: Panama";
    let result = is_palindrome(input);
    println!("{}", result);
}
```

