class TaskResource(Resource):
    def find_task_by_id(self, id):
        return next((task for task in tasks if task['id'] == id), None)

    def get(self, id):
        task = self.find_task_by_id(id)
        if not task:
            return {"error": "Task not found"}, 404
        return task

    def put(self, id):
        task = self.find_task_by_id(id)
        if not task:
            return {"error": "Task not found"}, 404
        task.update(request.json)
        return task

    def delete(self, id):
        global tasks
        tasks = [task for task in tasks if task['id'] != id]
        return {"result": "Task deleted"}

