```cpp
#include <iostream>
#include <queue>
using namespace std;

void deleteAndReverse(queue<int>& q) {
    int lastElement = q.back(); // Store the last element

    while (q.size() > 1) {
        q.pop(); // Delete elements except for the last one
    }

    q.push(lastElement); // Push the last element back to the queue

    // Reverse the order of the remaining elements
    queue<int> reversedQueue;
    while (!q.empty()) {
        reversedQueue.push(q.front());
        q.pop();
    }

    q = reversedQueue; // Assign the reversed queue back to the original queue
}

int main() {
