def add_items(list1, list2):
    p1 = {}
    p2 = {}

    # Count the occurrences of each item in list1
    for item in list1:
        p1[item] = p1.get(item, 0) + 1

    # Count the occurrences of each item in list2
    for item in list2:
        p2[item] = p2.get(item, 0) + 1

    # Create a result list
