from collections import deque

def astar_search(start_state, goal_state, get_successors):
    visited = set()
    queue = deque([(0, start_state)])
    path = {}
    while queue:
        _, current_state = queue.popleft()
        if current_state == goal_state:
            break
        if current_state in visited:
            continue
        visited.add(current_state)
        for successor_state in get_successors(current_state):
            if successor_state not in visited:
                queue.append((heuristic(successor_state), successor_state))
                path[successor_state] = current_state
    if current_state == goal_state:
        state = goal_state
        path_to_goal = [state]
        while state in path:
            state = path[state]
            path_to_goal.append(state)
        return path_to_goal[::-1]
    else:
        return None
```

This implementation uses a priority queue to store nodes based on their best heuristic value, which is the sum of the cost of reaching the node and the estimated cost of reaching the goal from the node.

