<head>
    <meta charset="UTF-8">
    <title>快速点击</title>
    <style>
        body{
            text-align: center;
        }
        #start{
            font-size: 30px;
            width: 200px;
            height: 50px;
            margin-top: 100px;
        }
        #number{
            font-size: 100px;
            margin-top: 50px;
            display: none;
        }
        #score{
            font-size: 30px;
            margin-top: 50px;
