    <button id="start" onclick="start()">开始</button>
    <div id="number"></div>
    <div id="score"></div>
    <button id="again" onclick="again()">再来一次</button>
    <script>
        var timer;
        var count = 0;
        var score = 0;
        function start(){
            document.getElementById("start").style.display = "none";
            document.getElementById("number").style.display = "block";
            timer = setInterval(showNumber, 5000);
        }
        function showNumber(){
            count++;
            if(count > 12){
                clearInterval(timer);
                document.getElementById("number").style.display = "none";
                document.getElementById("score").innerHTML = "总分数：" + score;
                document.getElementById("again").style.display = "block";
