#include <iostream>

const int STACK_SIZE = 100; // Maximum size of the stack memory
const int HEAP_SIZE = 100; // Maximum size of the heap memory

// Stack memory
int stackMemory[STACK_SIZE];
int* stackTop = stackMemory; // Pointer to the top of the stack memory

// Heap memory
int heapMemory[HEAP_SIZE];
int* heapTop = heapMemory; // Pointer to the top of the heap memory

// Function to allocate memory on the stack
int* allocateStackMemory(int size) {
    int* allocatedMemory = stackTop;
    stackTop += size;
    return allocatedMemory;
}

// Function to deallocate memory on the stack
void deallocateStackMemory(int* ptr) {
    stackTop = ptr;
}

// Function to allocate memory on the heap
int* allocateHeapMemory(int size) {
    int* allocatedMemory = heapTop;
    heapTop += size;
    return allocatedMemory;
}

// Function to deallocate memory on the heap
void deallocateHeapMemory(int* ptr) {
    heapTop = ptr;
}

// Function to print the contents of the stack and heap memory
void printMemory() {
    std::cout << "Stack Memory:" << std::endl;
    for (int* ptr = stackMemory; ptr < stackTop; ptr++) {
        std::cout << "Address: " << ptr << ", Value: " << *ptr << std::endl;
    }

    std::cout << "Heap Memory:" << std::endl;
    for (int* ptr = heapMemory; ptr < heapTop; ptr++) {
        std::cout << "Address: " << ptr << ", Value: " << *ptr << std::endl;
    }
}

int main() {
    // Allocate memory on the stack
    int* stackPtr1 = allocateStackMemory(5);
    for (int i = 0; i < 5; i++) {
        stackPtr1[i] = i;
    }
    printMemory();

    // Allocate memory on the heap
    int* heapPtr1 = allocateHeapMemory(5);
    for (int i = 0; i < 5; i++) {
        heapPtr1[i] = i;
    }
    printMemory();

    // Deallocate memory on the stack
    deallocateStackMemory(stackPtr1);
    printMemory();

    // Deallocate memory on the heap
    deallocateHeapMemory(heapPtr1);
    printMemory();

    return 0;
}

