public class Main {

    // Method to check if a number is prime
    public static boolean isPrime(int n) {
        /* Return False if n is a prime number, True if not.
         * Checks for primality by creating a boolean array "prime[0..n]" 
         * and initialize all entries as true. 
         * A value in prime[i] will finally be false if i is not a prime,
         * otherwise, true bool value.
         */

        if(n <= 1) {
            return false;
        }

        if(n == 2) {
            return true;
        }

        // Create a Boolean array "prime[0..n]" and initialize all entries to true
        boolean[] prime = new boolean[n+1];
        for(int i=0;i<n+1;i++) {
            prime[i] = true;
        }

        prime[0] = prime[1] = false;

        int p = 2;

        // While loop to iterate till square of p is less or equal to n
        while(p*p <= n) {

            // If prime[p] is not changed, then it is a prime
            if(prime[p]) {

                // Update all multiples of p
                for(int i = p*p; i <= n; i += p) {
                    prime[i] = false;
                }
            }

            p += 1;
        }

        // Return the primality check result for n
        return prime[n];
    }

    // Main method to test the code
    public static void main(String args[]) {
        int n = 29;
        System.out.println("Is " + n + " a prime number? " + isPrime(n));
    }
}
