fn sort_descending(arr: &mut [i32]) {
    let size = arr.len();
    for i in 0..size {
        for j in 0..size - i - 1 {
            if arr[j] < arr[j + 1] {
                let temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}
```

