def playfair_cipher(plain_text, keyword):
    # Step 1: Create the Playfair matrix
    matrix = create_playfair_matrix(keyword)

    # Step 2: Prepare the plain text
    plain_text = prepare_plain_text(plain_text)

    # Step 3: Encrypt the plain text using Playfair cipher
    encrypted_text = ""
    for i in range(0, len(plain_text), 2):
        pair = plain_text[i:i+2]
        encrypted_pair = encrypt_playfair_pair(pair, matrix)
        encrypted_text += encrypted_pair

    return encrypted_text


def create_playfair_matrix(keyword):
    # Step 1: Prepare the keyword
    keyword = prepare_keyword(keyword)

    # Step 2: Create the Playfair matrix
    matrix = [['' for _ in range(5)] for _ in range(5)]
    chars = set()

    i, j = 0, 0
    for char in keyword:
        if char not in chars:
            chars.add(char)
            matrix[i][j] = char
            j += 1
            if j == 5:
                i += 1
                j = 0

    for char in "ABCDEFGHIKLMNOPQRSTUVWXYZ":
        if char not in chars:
            matrix[i][j] = char
            j += 1
            if j == 5:
                i += 1
                j = 0

    return matrix


def prepare_keyword(keyword):
    keyword = keyword.upper().replace("J", "I")
    chars = set()

    prepared_keyword = ""
    for char in keyword:
        if char not in chars:
            chars.add(char)
            prepared_keyword += char

    return prepared_keyword


def prepare_plain_text(plain_text):
    plain_text = plain_text.upper().replace("J", "I")
    prepared_text = ""

    i = 0
    while i < len(plain_text):
        if i == len(plain_text) - 1 or plain_text[i] == plain_text[i+1]:
            prepared_text += plain_text[i] + "X"
            i += 1
        else:
            prepared_text += plain_text[i:i+2]
            i += 2

    if len(prepared_text) % 2 != 0:
        prepared_text += "X"

    return prepared_text


def encrypt_playfair_pair(pair, matrix):
    row1, col1 = find_position(pair[0], matrix)
    row2, col2 = find_position(pair[1], matrix)

    if row1 == row2:
        encrypted_pair = matrix[row1][(col1 + 1) % 5] + matrix[row2][(col2 + 1) % 5]
    elif col1 == col2:
        encrypted_pair = matrix[(row1 + 1) % 5][col1] + matrix[(row2 + 1) % 5][col2]
    else:
        encrypted_pair = matrix[row1][col2] + matrix[row2][col1]

    return encrypted_pair


def find_position(char, matrix):
    for i in range(5):
        for j in range(5):
            if matrix[i][j] == char:
                return i, j


def rail_fence_cipher(plain_text, num_rails):
    fence = [['\n' for _ in range(len(plain_text))]
             for _ in range(num_rails)]
    rail = 0
    direction = False

    for char in plain_text:
        fence[rail] = char
        if rail == 0 or rail == num_rails - 1:
            direction = not direction
        if direction:
            rail += 1
        else:
            rail -= 1

    encrypted_text = ''
    for i in range(num_rails):
        for j in range(len(plain_text)):
            if fence[i][j] != '\n':
                encrypted_text += fence[i][j]

    return encrypted_text


def encrypt(plain_text, keyword, num_rails):
    # Step 1: Encrypt using Playfair cipher
    playfair_encrypted = playfair_cipher(plain_text, keyword)

    # Step 2: Encrypt using Rail Fence cipher
    encrypted_text = rail_fence_cipher(playfair_encrypted, num_rails)

    return encrypted_text


