    closed = set()
    while queue:
        _, g, state, parent = heappop(queue)
        if is_target_state(state):
            return g
        if state in closed:
            continue
        closed.add(state)
        for i in range(4):
            next_state = move(state, i)
            if next_state is not None:
                heappush(queue, (h(next_state)+g+1, g+1, next_state, state))
    return None
start_state = (9, 6, 0, 13, 11, 8, 5, 12, 3, 14, 1, 10, 7, 15, 2, 4)
print(A_star(start_state)) # 输出结果为 32
```
