```python
from functools import wraps

def enforce_constraints(return_type, *arg_types):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Check argument types
            for i, arg in enumerate(args):
                if not isinstance(arg, arg_types[i]):
                    raise TypeError(
                        f"Expected argument '{func.__code__.co_varnames[i]}' to be of type '{arg_types[i].__name__}'"
                    )

            # Call the function
            result = func(*args, **kwargs)

            # Check return type
            if not isinstance(result, return_type):
                raise TypeError(
                    f"Expected return value to be of type '{return_type.__name__}'"
                )

            return result
        return wrapper
    return decorator
```

