Here's an example implementation of a search function for an AVL Tree in C#:

```csharp
using System;

class AVLNode {
    public int data;
    public AVLNode left;
    public AVLNode right;
    public int height;

    public AVLNode(int data) {
        this.data = data;
        this.height = 1;
    }
}

class AVLTree {
    private AVLNode root;

    private int GetHeight(AVLNode node) {
        if (node == null) {
            return 0;
        }
        return node.height;
    }

    private int GetBalanceFactor(AVLNode node) {
        if (node == null) {
            return 0;
        }
        return GetHeight(node.left) - GetHeight(node.right);
    }

    private AVLNode LeftRotate(AVLNode x) {
        AVLNode y = x.right;
        AVLNode z = y.left;

        y.left = x;
        x.right = z;

        x.height = Math.Max(GetHeight(x.left), GetHeight(x.right)) + 1;
        y.height = Math.Max(GetHeight(y.left), GetHeight(y.right)) + 1;

        return y;
    }

    private AVLNode RightRotate(AVLNode y) {
        AVLNode x = y.left;
        AVLNode z = x.right;

        x.right = y;
        y.left = z;

        y.height = Math.Max(GetHeight(y.left), GetHeight(y.right)) + 1;
        x.height = Math.Max(GetHeight(x.left), GetHeight(x.right)) + 1;

        return x;
    }

    public AVLNode Insert(AVLNode node, int data) {
        if (node == null) {
            return new AVLNode(data);
        }

        if (data < node.data) {
            node.left = Insert(node.left, data);
        } else if (data > node.data) {
            node.right = Insert(node.right, data);
        } else {
            return node;
        }

        node.height = Math.Max(GetHeight(node.left), GetHeight(node.right)) + 1;

        int balanceFactor = GetBalanceFactor(node);

        if (balanceFactor > 1 && data < node.left.data) { // Left Left Case
            return RightRotate(node);
        }

        if (balanceFactor > 1 && data > node.left.data) { // Left Right Case
            node.left = LeftRotate(node.left);
            return RightRotate(node);
        }

        if (balanceFactor < -1 && data > node.right.data) { // Right Right Case
            return LeftRotate(node);
        }

        if (balanceFactor < -1 && data < node.right.data) { // Right Left Case
            node.right = RightRotate(node.right);
            return LeftRotate(node);
        }

        return node;
    }

    public boolean Search(int data) {
        AVLNode current = root;
        while (current != null) {
            if (data < current.data) {
                current = current.left;
            } else if (data > current.data) {
                current = current.right;
            } else {
                return true; // Found the data
            }
        }
        return false; // Couldn't find the data
    }
}

class Program {
    static void Main(string[] args) {
        AVLTree tree = new AVLTree();

        tree.root = tree.Insert(tree.root, 12);
        tree.root = tree.Insert(tree.root, 23);
        tree.root = tree.Insert(tree.root, 34);
        tree.root = tree.Insert(tree.root, 45);

        Console.WriteLine(tree.Search(23)); // true
        Console.WriteLine(tree.Search(50)); // false
    }
}
```

The `AVLNode` class represents a node in the AVL Tree and contains fields for the data it stores, its left and right children, and its height. The `AVLTree` class contains functions for left and right rotations of the tree, inserting a new node into the tree, and searching for a particular element in the tree.

The `Insert` function first performs a standard BST insert operation for the new data, and then checks the tree for any balance violations. If any violations are found, it performs the necessary rotations to rebalance the tree.

The `Search` function starts at the root of the tree and recursively traverses the tree until the desired data is found or we reach the end of the tree without finding the data.

In the `Main` function, we create a new `AVLTree` object and insert four nodes with data 12, 23, 34, and 45. We then test the `Search` function by searching for the values 23 and 50, which should return true and false respectively.

