You can design a program in C++ to perform QuickSort on an array of integers using the following code:

```cpp
#include <iostream> 
using namespace std; 

// A function to swap values at two pointers 
void swap(int *a, int *b) 
{ 
    int t = *a; 
    *a = *b; 
    *b = t; 
} 

/* This function takes the last element as pivot, places 
   the pivot element at its correct position in the sorted 
   array, and places all smaller (smaller than pivot) 
   to the left of pivot and all greater elements to the right 
   of pivot */
int partition (int arr[], int low, int high) 
{ 
    int pivot = arr[high];    // pivot 
    int i = (low - 1);  // Index of the smaller element 

    for (int j = low; j <= high- 1; j++) 
    { 
        // If the current element is smaller than or 
        // equal to the pivot 
        if (arr[j] <= pivot) 
        { 
            i++;    // increment the index of the smaller element 
            swap(&arr[i], &arr[j]); 
        } 
    } 
    swap(&arr[i + 1], &arr[high]); 
    return (i + 1); 
} 

/* The main function that implements QuickSort 
   arr[] --> Array to be sorted, 
   low  --> Starting index, 
   high  --> Ending index */
void quickSort(int arr[], int low, int high) 
{ 
    if (low < high) 
    { 
        /* pi is the partitioning index, arr[p] is now 
           at the right place */
        int pi = partition(arr, low, high); 

        // Separately sort elements before 
        // partition and after partition 
        quickSort(arr, low, pi - 1); 
        quickSort(arr, pi + 1, high); 
    } 
} 

/* Function to print an array */
void printArray(int arr[], int size) 
{ 
    int i; 
    for (i=0; i < size; i++) 
        cout << arr[i] << " "; 
    cout << endl; 
} 

// Driver code 
int main() 
{ 
    int arr[] = {5, 7, 8, 1, 0}; 
    int n = sizeof(arr)/sizeof(arr[0]); 
    quickSort(arr, 0, n-1); 
    cout << "Sorted array: \n"; 
    printArray(arr, n); 
    return 0; 
}
```

