def generate_lucas_sequence(n):
    lucas_sequence = [2, 1] # Initialize the Lucas sequence with the first two prime numbers
    if n == 1:
        return [2]
    elif n == 2:
        return lucas_sequence
    else:
        for i in range(2, n):
            lucas_sequence.append(lucas_sequence[i-1] + lucas_sequence[i-2])
        return lucas_sequence

