```python
import threading
from Queue import Queue, Empty
import time

class MultiThreadedCrawler:
    def __init__(self, config, threads=10):
        self.config = config
        self.threads = threads
        self.write_lock = threading.Lock()
        self.dispatch_queue = Queue()
        self.shutdown_event = threading.Event()

    def start_workers(self):
        self.shutdown_event.clear()
        for _ in range(self.threads):
            worker = threading.Thread(target=self.process_queue)
            worker.daemon = True
            worker.start()

    def process_queue(self):
        while not self.shutdown_event.is_set():
            try:
                callback = self.dispatch_queue.get(timeout=1)
            except Empty:
                continue

            callback()
            self.dispatch_queue.task_done()

    def run_crawler(self, resource):
        try:
            self.start_workers()
            resource.accept(self)
            self.dispatch_queue.join()
        finally:
            self.shutdown_event.set()
            time.sleep(2)

    def dispatch(self, callback):
        self.dispatch_queue.put(callback)

    def write_resource(self, resource):
        with self.write_lock:
            self.config.storage.write(resource)

    def handle_child_error(self, error):
        warning_message = '{}\n'.format(error)
        with self.write_lock:
            self.config.storage.warning(warning_message)
        self.config.progresser.on_warning(error)

    def update_resource(self, resource):
        try:
            with self.write_lock:
                self.config.storage.update(resource)
        except Exception as e:
            LOGGER.exception(e)
            self.config.progresser.on_error(e)
            raise
