public void exEquityCurve(object dataObj)
{
    List<structEquity> dataList = (List<structEquity>)dataObj;

    using (SqlConnection connection = new SqlConnection(connectionString))
    {
        connection.Open();

        using (SqlBulkCopy bulkCopy = new SqlBulkCopy(connection))
        {
            bulkCopy.DestinationTableName = "dbo.tblResultEquityCurve";
            bulkCopy.ColumnMappings.Add("dTime", "DTime");
            bulkCopy.ColumnMappings.Add("Equity", "Equity");

            DataTable dataTable = new DataTable();
            dataTable.Columns.Add("dTime", typeof(DateTime));
            dataTable.Columns.Add("Equity", typeof(decimal));

            foreach (structEquity equity in dataList)
            {
                DataRow row = dataTable.NewRow();
                row["dTime"] = equity.dTime;
                row["Equity"] = equity.Equity;
                dataTable.Rows.Add(row);
            }

            bulkCopy.WriteToServer(dataTable);
        }

        connection.Close();
    }
}
