def is_prime(n):
    """Check if integer n is a prime number"""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_next_prime(n):
    """Find the next prime number larger than n"""
    candidate = n + 1
    while True:
        if is_prime(candidate):
            return candidate
        candidate += 1
```

