import inspect

def call_func_with_args(f, kwargs):
    signature = inspect.signature(f)
    parameters = signature.parameters
    args = []

    for param_name in parameters:
        param = parameters.get(param_name)
        if param is not None and param_name in kwargs:
            args.append(kwargs[param_name])

