public Node mergeLists(Node l1, Node l2) {
    if(l1 == null) {
        return l2;
    }
    if(l2 == null) {
        return l1;
    }

    /* If the value of the first linked list is smaller than the second one, 
       we link the next node to the remaining merged list. If the value of the first 
       linked list is larger, the first and second lists are swapped. */
    if(l1.val <= l2.val) {
        l1.next = mergeLists(l1.next, l2);
