            while (taskIdx < taskIndices.length && tasks[taskIndices[taskIdx]][0] <= time) {
                int idx = taskIndices[taskIdx];
                minHeap.add(new int[]{idx, tasks[idx][1]});
                taskIndices[taskIdx] = null;
                taskIdx++;
            }

