To solve this problem, you can use the Hierholzer's algorithm to find the Eulerian cycle in the given graph. First, represent the graph using an adjacency list or matrix to store the edges between vertices. Then, use a depth-first search (DFS) to traverse the graph and find the Eulerian cycle. Once the cycle is found, verify if it visits each edge exactly once and returns to the starting vertex. If it does, output that the graph has an Eulerian cycle; otherwise, output that it does not.

Here's a sample implementation in Python using an adjacency list representation of the graph:

```python
from collections import defaultdict

class Graph:
    def __init__(self, vertices):
        self.graph = defaultdict(list)
        self.V = vertices

    def add_edge(self, u, v):
        self.graph[u].append(v)
        self.graph[v].append(u)

    def dfs(self, v, visited):
        visited[v] = True
        for i in self.graph[v]:
            if not visited[i]:
                self.dfs(i, visited)

    def is_connected(self):
        visited = {v: False for v in range(self.V)}
        for i in range(self.V):
            if len(self.graph[i]) > 0:
                break
        if i == self.V - 1:
            return True
        self.dfs(i, visited)
        for i in range(self.V):
            if not visited[i] and len(self.graph[i]) > 0:
                return False
        return True

    def is_eulerian_cycle(self):
        if not self.is_connected():
            return False
        odd_degree_count = 0
        for v in self.graph:
            if len(self.graph[v]) % 2 != 0:
                odd_degree_count += 1
            if odd_degree_count > 2:
                return False
        return odd_degree_count == 0 or odd_degree_count == 2
```

