#include <stdio.h>

int main() {
    int arr[] = {65, 69, 28, 16, 99, 105};
    int n = sizeof(arr)/sizeof(arr[0]);
    int i, j, temp;

    for (i = 0; i < n; i++) { 
        for (j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j+1]) { 
                temp = arr[j]; 
                arr[j] = arr[j+1]; 
                arr[j+1] = temp; 
            }
        }
    }

