  private Point computeCentroid(List<Point> cluster) {
    double sumX = 0.0, sumY = 0.0;

    for (Point point : cluster) {
      sumX += point.x;
      sumY += point.y;
    }

    double centroidX = sumX / cluster.size();
    double centroidY = sumY / cluster.size();

    return new Point(centroidX, centroidY);
