      distance = singleLinkage(cluster1, cluster2);
    } else {
      distance = completeLinkage(cluster1, cluster2);
    }

    return distance;
  }

  private double singleLinkage(List<Map<String, Object>> cluster1, List<Map<String, Object>> cluster2) {
    double minDistance = Double.POSITIVE_INFINITY;

    for (Map<String, Object> point1 : cluster1) {
      for (Map<String, Object> point2 : cluster2) {
        double distance = computeDistance(point1, point2);

        if (distance < minDistance) {
          minDistance = distance;
        }
      }
    }

    return minDistance;
  }

  private double completeLinkage(List<Map<String, Object>> cluster1, List<Map<String, Object>> cluster2) {
    double maxDistance = Double.NEGATIVE_INFINITY;

    for (Map<String, Object> point1 : cluster1) {
      for (Map<String, Object> point2 : cluster2) {
