def count_uppercase_vowels(words):
    if not words or not all(isinstance(word, str) for word in words):
        raise ValueError('Input list should contain only non-empty strings.')

    vowel_counter = {'A': 0, 'E': 0, 'I': 0, 'O': 0, 'U': 0}
    for word in words:
        for vowel in vowel_counter:
            vowel_counter[vowel] += word.count(vowel)

    total_vowels_count = sum(vowel_counter.values())
    vowels_by_frequency = sorted(
        ((k, v) for k, v in vowel_counter.items() if v > 0),
