def generate_binary_encodings(n):
    if n < 1:
        return []
    encodings = []
    for i in range(2**n):
        binary_string = ""
        for j in range(n):
            if i & (1 << j):
                binary_string = "1" + binary_string
            else:
                binary_string = "0" + binary_string
        encodings.append(binary_string)
    return encodings
